    public static FType traitOf(FType t) {
        if (t instanceof FTypeTuple) {
            List<FType> elements = ((FTypeTuple) t).getTypes();
            List<FType> read = new ArrayList<FType>(elements.size());
            boolean changed = false;
            for (FType e : elements) {
                FType r = traitOf(e);
                changed |= r != e;
                read.add(r);
