            change |= injectTraitMembersForDesugaring(linker, cw);
        }

        change |= injectLibraryTraits(components, lib);
        change |= injectLibraryTraits(components, natives);
    }

    for (ForeignComponentWrapper cw : foreigns) {

        cw.populateOne();
    }
